// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getUser, updateUser } from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Declaration of variables
    const users = "testbot-admin";

    const usersGetResponse = await getUser(client, users, 200);
    expect(usersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersGetResponse, "response.username"), 'username').toBe("testbot-admin");
    expect(getResponseValue(usersGetResponse, "response.id"), 'id').toBeGreaterThan(0);

    const usersPutResponse = await updateUser(
        client,
        getResponseValue(usersGetResponse, "response.id"),
        getResponseValue(usersGetResponse, "response.name"),
        getResponseValue(usersGetResponse, "response.username"),
        true,
        "testbotpassword123",
        200
    );
    expect(usersPutResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersPutResponse, "response.username"), 'username').toBe("testbot-admin");
    expect(getResponseValue(usersPutResponse, "response.id"), 'id').toBe(getResponseValue(usersGetResponse, "response.id"));

    const usersGet1Response = await getUser(client, getResponseValue(usersGetResponse, "response.username"), 404);
    expect(usersGet1Response.statusCode, 'status code').toBe(404);
    expect(getResponseValue(usersGet1Response, "response"), 'response').toBe("User not found.");
    expect(getResponseValue(usersGet1Response, "response.username"), 'username carries no value').toBeNull();

    const usersPut1Response = await updateUser(
        client,
        getResponseValue(usersGetResponse, "response.id"),
        getResponseValue(usersGetResponse, "response.name"),
        getResponseValue(usersGetResponse, "response.username"),
        false,
        "testbotpassword123",
        200
    );
    expect(usersPut1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersPut1Response, "response.username"), 'username').toBe("testbot-admin");
});
